#!/usr/bin/env bash
# Rebuild p3sys.wasm and re-take testdata/p3sys.reading (#1232, ADR 0119).
#
# **Run deliberately and out of CI.** The committed p3sys.wasm and p3sys.reading ARE the artefacts; this
# script exists so they can be regenerated when a tool moves, not so anything on the test path invokes a Rust
# toolchain or wasmtime (asynclift/build.sh's shape: commit the oracle's reading, never depend on the oracle at
# test time).
#
# Offline: cargo resolves wit-bindgen 0.61.1 and its dependencies from the local registry (`--offline`, and
# `--locked` against the committed Cargo.lock), so a rebuild fetches nothing.
#
# ## Pitfalls already paid for
#
#   * `rustc +nightly` resolves to Homebrew's 1.99.1 on this machine, which has no wasm32-wasip3 target. The
#     nightly is named by its toolchain directory, and cargo is handed that rustc by RUSTC, not by PATH.
#   * The pinned WIT is not committed. It is the WASI 0.3.0 WIT the nightly's std vendors for its own bindings
#     (library/vendor/wasip3-0.8.0+wasi-0.3.0/wit/deps), staged beside wit/world.wit in a scratch copy of the
#     crate, so the guest's bindings and std's are generated from one WIT.
#   * The build runs in that scratch copy, never in the tree, so no target/ directory appears under testdata
#     and a warm cache from another tree cannot answer for this one.
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
repo=$(cd "$here/../../../.." && pwd)
: "${NIGHTLY:=$HOME/.rustup/toolchains/nightly-aarch64-apple-darwin}"
: "${CARGO:=$NIGHTLY/bin/cargo}"
: "${RUSTC:=$NIGHTLY/bin/rustc}"
: "${WASM_TOOLS:=wasm-tools}"
# The pinned oracle that scripts/oracle-fetch.sh installs, never the wasmtime on PATH (50.0.1 on this machine).
# A worktree has no .oracle of its own, so the main checkout's is the fallback.
: "${WASMTIME:=$repo/.oracle/wasmtime-49.0.3/wasmtime}"
[ -x "$WASMTIME" ] || WASMTIME="$HOME/src/burroughs/.oracle/wasmtime-49.0.3/wasmtime"
WIT_DEPS="$NIGHTLY/lib/rustlib/src/rust/library/vendor/wasip3-0.8.0+wasi-0.3.0/wit/deps"

for t in "$CARGO" "$RUSTC" "$WASMTIME"; do
	[ -x "$t" ] || { echo "build.sh: $t is not executable" >&2; exit 2; }
done
[ -d "$WIT_DEPS" ] || { echo "build.sh: no pinned WIT at $WIT_DEPS" >&2; exit 2; }

: "${EXPECT_RUSTC:=rustc 1.100.0-nightly}"
: "${EXPECT_WASM_TOOLS:=wasm-tools 1.258.0}"
: "${EXPECT_WASMTIME:=wasmtime 49.0.3}"
expect_version() { # expect_version <tool> <"name version">: the first two fields of `<tool> --version`
	got=$("$1" --version | awk 'NR == 1 {print $1, $2}')
	[ "$got" = "$2" ] || {
		echo "build.sh: $1 is '$got', and the committed artefacts were built and read with '$2'." >&2
		echo "          Rebuild and re-take on the new version, and move the expectation in the same commit." >&2
		exit 2
	}
}
expect_version "$RUSTC" "$EXPECT_RUSTC"
expect_version "$WASM_TOOLS" "$EXPECT_WASM_TOOLS"
expect_version "$WASMTIME" "$EXPECT_WASMTIME"

scratch_root=${TMPDIR:-/tmp}
[ -d "$HOME/.xtmp" ] && scratch_root="$HOME/.xtmp"
work=$(mktemp -d "$scratch_root/p3sys-build.XXXXXX")
trap 'rm -rf "$work"' EXIT
cp -R "$here/Cargo.toml" "$here/Cargo.lock" "$here/src" "$work/"
mkdir -p "$work/wit/deps"
cp "$here/wit/world.wit" "$work/wit/"
for f in random clocks cli filesystem sockets; do cp "$WIT_DEPS/$f.wit" "$work/wit/deps/"; done

# The output is deleted before the build, so a failed build cannot leave the old artefact to be read.
rm -f "$here/p3sys.wasm"
( cd "$work" && RUSTC="$RUSTC" CARGO_TARGET_DIR="$work/target" \
	"$CARGO" build --offline --locked --release --target wasm32-wasip3 )
cp "$work/target/wasm32-wasip3/release/p3sys.wasm" "$here/p3sys.wasm"
"$WASM_TOOLS" validate --features all "$here/p3sys.wasm"

# The reading. stdin is /dev/null and stdout and stderr are files, so wasmtime sees no terminal and answers
# none for each get-terminal-*, as a host that is handed io.Writers does.
"$WASMTIME" run "$here/p3sys.wasm" </dev/null >"$work/stdout" 2>"$work/stderr" && code=0 || code=$?
{
	echo "# Committed reading of internal/component/testdata/p3sys/p3sys.wasm (#1232; ADR 0119)."
	echo "# Regenerated by p3sys/build.sh; never hand-edited."
	echo "# Built:       p3sys/build.sh ($("$RUSTC" --version | awk '{print $1, $2}'), wit-bindgen 0.61.1, wasm32-wasip3)"
	echo "# Invocation:  wasmtime run p3sys.wasm </dev/null"
	echo "# Engine:      $("$WASMTIME" --version), $(uname -s | tr 'A-Z' 'a-z')/$(uname -m | sed 's/aarch64/arm64/')."
	echo "# exit:        $code"
	echo "#"
	echo "# Each line below is one channel's line, prefixed by the channel's name."
	sed 's/^/stdout: /' "$work/stdout"
	sed 's/^/stderr: /' "$work/stderr"
} >"$repo/internal/component/testdata/p3sys.reading"
cat "$repo/internal/component/testdata/p3sys.reading"
shasum -a 256 "$here/p3sys.wasm"
wc -c <"$here/p3sys.wasm"
